sqlReaderQuery.value:
@concat(
    'SELECT MAX(last_watermark_value) AS last_watermark_value ',
    'FROM dbo.vb_tbl_watermark ',
    'WHERE job_id = ',
    string(pipeline().parameters.p_job_id)
)

expression.value:
@or(
    equals(
        activity('Lookup_Table_Watermark').output.firstRow.last_watermark_value,
        null
    ),
    and(
        not(
            equals(
                activity('Lookup_Current_Table_Watermark').output.firstRow.current_watermark,
                null
            )
        ),
        greater(
            ticks(activity('Lookup_Current_Table_Watermark').output.firstRow.current_watermark),
            ticks(activity('Lookup_Table_Watermark').output.firstRow.last_watermark_value)
        )
    )
)
